<script setup>
import {ref,defineAsyncComponent,onMounted} from 'vue'
import Icon from '../Icon.vue'
import MobileVerification from './MobileVerification.vue'
import {previewMode} from '../preview/mode'
const Preview=previewMode?defineAsyncComponent(()=>import('../preview/PreviewShell.vue')):null
import {request} from './client'
const Campus=defineAsyncComponent(()=>import('../App.vue'))
const Owner=defineAsyncComponent(()=>import('./SuperAdmin.vue'))
const Profile=defineAsyncComponent(()=>import('../commerce/ProfileEditor.vue'))
const Signup=defineAsyncComponent(()=>import('./RegistrationFlow.vue'))
const localPreviewAvailable=import.meta.env.DEV&&['localhost','127.0.0.1','[::1]'].includes(location.hostname)
const session=ref(null),error=ref(''),busy=ref(true),selected=ref('Student'),signup=ref(false),dark=ref(false)
const roles=[{name:'Student',icon:'GraduationCap',text:'Learn, explore and grow.'},{name:'Teacher',icon:'BookOpen',text:'Individual teacher or institute.'}]
async function google(){try{const r=await request('portal_policy','google_start');const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='accounts.google.com')throw Error('Google sign-in is unavailable');location.assign(u.href)}catch(e){error.value=e.message}}
async function connect(){busy.value=true;error.value='';try{session.value=await request('portal_session','current',{},'GET');if(session.value.csrf_token)window.csrf_token=session.value.csrf_token}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{if(!previewMode)connect()})
</script>
<template>
  <Preview v-if="previewMode"/>
  <Owner v-else-if="session?.role==='Super Admin'" :session="session"/>
  <Campus v-else-if="session?.member"/>
  <div v-else-if="session?.authenticated" class="entry-onboarding"><h1>Let’s make this space yours.</h1><p>Complete your profile and mobile verification before your workspace is activated.</p><p>Account type: {{session.onboarding_kind}}</p><MobileVerification/><Profile :key="session.onboarding_kind" :member="{user:session.user,full_name:session.user,role:session.onboarding_kind==='Institute'?'Admin':session.onboarding_kind}" @saved="connect"/><a href="/me">Account settings</a><a href="/api/method/logout">Sign out</a></div>
  <Signup v-else-if="signup" @back="signup=false" @dashboard="connect"/>
  <main v-else class="sisu-entry" :class="{'entry-dark':dark}">
    <header><a href="#" class="entry-brand">sisu<span>✦</span></a><div><span class="entry-note">A little space. A world of possibility.</span><button class="entry-icon" @click="dark=!dark" :aria-label="dark?'Light mode':'Dark mode'"><Icon :name="dark?'Sun':'Moon'"/></button></div></header>
    <div class="entry-layout"><section class="entry-story"><span class="entry-kicker">YOUR NEXT CHAPTER STARTS HERE</span><h1>Big dreams.<br>Little steps.<br><em>Your space.</em></h1><p>A calm home for learning, teaching and all the wonderful things you’ll become.</p><div class="entry-garden" aria-hidden="true"><span class="entry-orbit"></span><div class="entry-book"><Icon name="BookOpen" :size="75"/><span>Keep growing.</span></div><span class="garden-spark">✧</span><span class="garden-leaf">❧</span><span class="garden-dot"></span></div><footer><span>✦ A place to belong</span><span>Made for curious minds</span></footer></section>
    <section class="entry-card"><span class="entry-kicker">COME ON IN</span><h2>It’s good to see you.</h2><p>Choose your space to get started.</p><div class="entry-roles"><button v-for="r in roles" :key="r.name" @click="selected=r.name" :class="{selected:selected===r.name}" :aria-pressed="selected===r.name"><span><Icon :name="r.icon" :size="21"/></span><div><strong>{{r.name}}</strong><small>{{r.text}}</small></div><i>{{selected===r.name?'✓':'›'}}</i></button></div>
      <button v-if="selected==='Student'" class="entry-primary" @click="google">G · Continue with Google</button><a v-else class="entry-primary" href="/login?redirect-to=/campus">Sign in as provider →</a><p class="entry-secure"><Icon name="ShieldCheck" :size="15"/>Your account determines your permissions.</p><div class="entry-divider"><span>NEW TO SISU?</span></div><button class="entry-secondary" @click="signup=true">Create your account <Icon name="Plus" :size="16"/></button><p class="entry-subtle">Students use Google. Teachers and institutes apply for review, then set a password through a secure email.</p><details class="entry-owner"><summary>Platform owner access</summary><a href="/login?redirect-to=/campus">Sign in to Super Admin →</a><p>Only the configured, verified owner account can access the separate control room.</p></details>
      <a v-if="localPreviewAvailable" class="entry-primary" style="margin-top:20px" href="/?preview=1">Explore the full platform preview →</a><div v-if="error" class="entry-status" role="status"><span class="status-dot"></span><div><strong>Local preview</strong><p>{{error}}</p><button @click="connect" :disabled="busy">Check connection again</button></div></div><p v-else-if="busy" role="status">Checking your session…</p>
    </section></div><footer class="entry-bottom">Your classes. Your people. Your own pace.<span>Secure access · No sample accounts</span></footer>
  </main>
</template>
<style>
.sisu-entry{--entry-bg:#f6f2fc;--entry-card:#fffcff;--entry-ink:#3b3050;--entry-muted:#7b708b;--entry-border:#e5dcef;min-height:100vh;background:var(--entry-bg);color:var(--entry-ink);padding:34px max(28px,6vw);font-family:Inter,system-ui,sans-serif}.sisu-entry.entry-dark{--entry-bg:#201a2d;--entry-card:#2c243b;--entry-ink:#eee5fc;--entry-muted:#b3a5c5;--entry-border:#453854}.sisu-entry header,.sisu-entry header>div,.entry-bottom,.entry-story footer{display:flex;align-items:center;justify-content:space-between;gap:25px}.entry-brand{font-size:39px;font-weight:800;letter-spacing:-3px;color:inherit;text-decoration:none}.entry-brand span{color:#a28ac6;font-size:22px;margin-left:8px}.entry-note{font-size:12px;color:var(--entry-muted)}.entry-icon{background:var(--entry-card);border:1px solid var(--entry-border);border-radius:50%;padding:12px;color:inherit;cursor:pointer}.entry-layout{display:grid;grid-template-columns:1.1fr 1fr;gap:9%;max-width:1240px;margin:70px auto 50px;align-items:center}.entry-kicker{font-size:10px;letter-spacing:2.7px;font-weight:600;color:var(--entry-muted)}.entry-story h1{font-size:clamp(44px,5vw,74px);line-height:1.12;letter-spacing:-3px;margin:27px 0}.entry-story h1 em{color:#9470bd;font-style:normal}.entry-story>p{max-width:365px;color:var(--entry-muted);font-size:15px;line-height:1.9}.entry-garden{position:relative;height:210px;margin:20px 0;display:grid;place-items:center;max-width:370px}.entry-book{width:150px;height:166px;background:linear-gradient(150deg,#eee0ff,#bc9ce1);border:5px solid #fff8;border-radius:26px 38px 28px 12px;box-shadow:15px 16px 0 #a38bb43a,20px 24px 35px #8c73a51c;transform:rotate(-10deg);display:flex;align-items:center;justify-content:center;gap:13px;flex-direction:column;color:#755398}.entry-book span{font-size:12px;font-weight:600}.entry-orbit{position:absolute;width:310px;height:145px;border:1px solid #bdaaca60;border-radius:50%;transform:rotate(-20deg)}.garden-spark{position:absolute;right:25px;top:15px;color:#a082c5;font-size:62px}.garden-leaf{position:absolute;left:0;bottom:0;color:#88a797;font-size:120px;transform:rotate(-30deg)}.garden-dot{width:22px;height:22px;background:#e7c59d;border-radius:50%;position:absolute;bottom:30px;right:38px}.entry-story footer{justify-content:flex-start;font-size:11px;color:var(--entry-muted)}.entry-card{padding:38px;border:1px solid var(--entry-border);border-radius:30px;background:var(--entry-card);box-shadow:0 25px 70px #6a43860b}.entry-card h2{font-size:30px;letter-spacing:-1px;margin:14px 0}.entry-card>p{font-size:13px;color:var(--entry-muted);line-height:1.7}.entry-roles{display:grid;gap:10px;margin:26px 0}.entry-roles button{display:flex;align-items:center;gap:14px;width:100%;padding:15px;border:1px solid var(--entry-border);border-radius:15px;background:transparent;color:inherit;cursor:pointer;text-align:left}.entry-roles button.selected{background:#a98ac01a;border-color:#a98ac0}.entry-roles button>span{background:#a98ac019;padding:10px;border-radius:12px;color:#9674b4}.entry-roles button div{display:grid;gap:5px;flex:1}.entry-roles strong{font-size:13px}.entry-roles small{font-size:11px;color:var(--entry-muted)}.entry-roles i{font-style:normal;color:#9874b8}.entry-primary,.entry-secondary{display:flex;align-items:center;justify-content:center;gap:15px;border-radius:13px;padding:16px;font-size:13px;font-weight:600;width:100%;text-decoration:none;cursor:pointer}.entry-primary{background:#8c6ab0;color:#fff;box-shadow:0 7px 16px #8c6ab020}.entry-secondary{border:1px solid var(--entry-border);color:inherit;background:transparent}.entry-secure{display:flex;align-items:center;justify-content:center;gap:7px;font-size:10px!important;margin:13px 0}.entry-divider{border-top:1px solid var(--entry-border);text-align:center;margin:26px 0 20px;height:0}.entry-divider span{position:relative;top:-8px;padding:0 14px;background:var(--entry-card);font-size:9px;letter-spacing:1px;color:var(--entry-muted)}.entry-subtle{font-size:10px!important;text-align:center;margin:14px 8px}.entry-owner{font-size:11px;margin-top:24px;color:var(--entry-muted);line-height:1.7}.entry-owner summary{cursor:pointer}.entry-owner a{display:block;margin-top:12px;color:#9674b4}.entry-status{margin-top:18px;padding:13px;display:flex;gap:10px;border:1px solid var(--entry-border);border-radius:12px;font-size:10px;color:var(--entry-muted);line-height:1.6}.entry-status p{margin:4px 0}.entry-status button{border:0;background:none;padding:0;text-decoration:underline;color:inherit;font-size:10px;cursor:pointer}.status-dot{background:#c7a478;width:6px;height:6px;border-radius:50%;margin-top:5px;flex-shrink:0}.entry-bottom{font-size:11px;color:var(--entry-muted);max-width:1240px;margin:auto}.entry-onboarding{max-width:780px;margin:70px auto;padding:25px}.entry-onboarding>a{margin-right:20px}@media(max-width:850px){.entry-layout{gap:35px;margin-top:40px}.entry-card{padding:25px}.entry-story h1{font-size:46px}.entry-note{display:none}.entry-garden{transform:scale(.85);transform-origin:left}}@media(max-width:640px){.entry-layout{grid-template-columns:1fr;margin-top:35px}.entry-story h1{font-size:44px}.entry-story>p{font-size:13px}.entry-garden,.entry-story footer{display:none}.entry-bottom{flex-direction:column;gap:10px;text-align:center}.entry-card h2{font-size:26px}}
</style>
